T = {
'card34_title': ("Asking for a Raise", "Pedir un aumento"),
'card35_opt0_res0': ("The manager agrees to a trial. {0.SimFirstName} is more productive and proves it!\n\nDid you know? To work remotely and safely, you go through the company VPN.", "El responsable acepta una prueba. ¡{0.SimFirstName} rinde más y lo demuestra!\n\n¿Lo sabías? Para teletrabajar con seguridad, se usa la VPN de la empresa."),
'card35_opt0_res1': ("Refused: \"We can't supervise remote work.\"\n\nDid you know? Remote work is often negotiated with clear goals to reach.", "Rechazado: «No podemos supervisar el trabajo a distancia.»\n\n¿Lo sabías? El teletrabajo suele negociarse con objetivos claros que cumplir."),
'card35_opt0': ("Propose a one-day-a-week trial", "Proponer una prueba de un día por semana"),
'card35_opt1_res0': ("Nothing changes.\n\nDid you know? Remote work is governed by a company agreement or policy.", "Nada cambia.\n\n¿Lo sabías? El teletrabajo se regula con un acuerdo de empresa o una política interna."),
'card35_opt1': ("Don't ask", "No pedir nada"),
'card35_text': ("{0.SimFirstName}'s friends get 2 remote days a week. What about asking for the same?", "Unos amigos de {0.SimFirstName} tienen 2 días de teletrabajo por semana. ¿Y si pidiera lo mismo?"),
'card35_title': ("Remote Work", "El teletrabajo"),
'card36_opt0_res0': ("The intern sets up a GLPI server from A to Z. They're thrilled, and {0.SimFirstName} learned how to explain things.\n\nDid you know? During an internship, a real, well-documented project is perfect for your exams and portfolio!", "El becario instala un servidor GLPI de principio a fin. Está encantado, y {0.SimFirstName} ha aprendido a explicar.\n\n¿Lo sabías? En unas prácticas, una misión real y bien documentada es perfecta para tus exámenes y tu portafolio."),
'card36_opt0': ("Give them a real project", "Confiarle una misión de verdad"),
'card36_opt1_res0': ("The intern is bored… and says so in their internship report.\n\nDid you know? A successful internship can lead to a job or a work-study contract: it's a win for the company too.", "El becario se aburre… y lo dice en su memoria de prácticas.\n\n¿Lo sabías? Unas prácticas exitosas pueden acabar en contrato o en formación dual: la empresa también sale ganando."),
'card36_opt1': ("Have them make photocopies", "Ponerle a hacer fotocopias"),
'card36_text': ("An IT student intern joins the team, and {0.SimFirstName} has to mentor them.", "Un becario de informática llega al equipo, y {0.SimFirstName} tiene que tutelarlo."),
'card36_title': ("The Student Intern", "El becario de informática"),
'card37_opt0_res0': ("{0.SimFirstName} suggests secure sharing on the company server. The data protection officer approves.\n\nDid you know? The GDPR requires personal data to be protected. Regulators can hand out big fines.", "{0.SimFirstName} propone compartir los archivos de forma segura en el servidor de la empresa. El delegado de protección de datos lo aprueba.\n\n¿Lo sabías? El RGPD obliga a proteger los datos personales. Las autoridades (en España, la AEPD) pueden imponer multas enormes."),
'card37_opt0': ("Refuse and offer a compliant solution", "Negarse y proponer una solución conforme"),
'card37_opt1_res0': ("The Drive was public… The data leaked and the regulator opens an investigation!\n\nDid you know? After a data breach, the company must notify the authority within 72 hours.", "El Drive era público… ¡Los datos se han filtrado y la autoridad abre una investigación!\n\n¿Lo sabías? Ante una brecha de datos, la empresa debe avisar a la autoridad en un plazo de 72 horas."),
'card37_opt1_res1': ("No problem… for now.\n\nDid you know? The GDPR applies even if nobody notices.", "Ningún problema… por ahora.\n\n¿Lo sabías? El RGPD se aplica aunque nadie se dé cuenta."),
'card37_opt1': ("Let it happen", "Dejarlo pasar"),
'card37_text': ("The sales team wants to put the customer file (with bank details) on a personal Google Drive \"to go faster\".", "El equipo comercial quiere poner el fichero de clientes (con datos bancarios) en un Google Drive personal «para ir más rápido»."),
'card37_title': ("Customer Files and GDPR", "Ficheros de clientes y RGPD"),
'card38_opt0_res0': ("{0.SimFirstName} leaves with 30 contacts and plenty of ideas!\n\nDid you know? A professional network helps a lot to find an internship, a work-study job or a job.", "¡{0.SimFirstName} vuelve con 30 contactos y muchas ideas!\n\n¿Lo sabías? La red profesional ayuda mucho a encontrar prácticas, formación dual o empleo."),
'card38_opt0_res1': ("A few nice chats, nothing more.\n\nDid you know? Keeping your résumé up to date on LinkedIn helps after a trade show.", "Algunas charlas agradables, sin más.\n\n¿Lo sabías? Tener el currículum al día en LinkedIn ayuda después de una feria."),
'card38_opt0': ("Meet as many people as possible", "Conocer al máximo de gente"),
'card38_opt1_res0': ("{0.SimFirstName} discovers lots of new technologies.\n\nDid you know? Keeping up with technology (tech watch) is part of the job.", "{0.SimFirstName} descubre muchas tecnologías nuevas.\n\n¿Lo sabías? Mantenerse al día de la tecnología (vigilancia tecnológica) forma parte del oficio."),
'card38_opt1': ("Attend the technical talks", "Asistir a las conferencias técnicas"),
'card38_text': ("The company sends {0.SimFirstName} to a big tech trade show for a day.", "La empresa envía a {0.SimFirstName} a una gran feria tecnológica durante un día."),
'card38_title': ("The Tech Trade Show", "La feria tecnológica"),
'card39_opt0_res0': ("The manager spreads the work out better. The colleague thanks {0.SimFirstName}.\n\nDid you know? Burnout is common in IT, especially with on-call duty.", "El responsable reparte mejor el trabajo. El compañero da las gracias a {0.SimFirstName}.\n\n¿Lo sabías? El agotamiento profesional (burnout) es frecuente en informática, sobre todo con las guardias."),
'card39_opt0': ("Talk to the manager", "Hablarlo con el responsable"),
'card39_opt1_res0': ("{0.SimFirstName} helps a lot, but comes home exhausted.\n\nDid you know? Helping is good, but you also have to know how to say no to protect yourself.", "{0.SimFirstName} ayuda mucho, pero vuelve a casa muy cansado.\n\n¿Lo sabías? Ayudar está bien, pero también hay que saber decir que no para protegerse."),
'card39_opt1': ("Take over part of their work", "Asumir parte de su trabajo"),
'card39_text': ("A colleague keeps piling up overtime and seems close to burnout.", "Un compañero encadena horas extra y parece al borde del agotamiento."),
'card39_title': ("The Exhausted Colleague", "El compañero agotado"),
'card40_opt0_res0': ("One week at school, two weeks at work: it's intense, but {0.SimFirstName} is progressing very fast.\n\nDid you know? Many students continue their studies through work-study programs: the school is paid for and you earn a salary.", "Una semana en clase, dos en la empresa: es intenso, pero {0.SimFirstName} progresa muy rápido.\n\n¿Lo sabías? Muchos estudiantes siguen formándose en modalidad dual: la formación está pagada y se cobra un sueldo."),
'card40_opt0': ("Accept", "Aceptar"),
'card40_opt1_res0': ("{0.SimFirstName} prefers to stay full-time.\n\nDid you know? You can also progress through certifications, without going back to school.", "{0.SimFirstName} prefiere seguir a jornada completa.\n\n¿Lo sabías? También se puede progresar con certificaciones, sin volver a estudiar."),
'card40_opt1': ("Decline", "Rechazar"),
'card40_text': ("The company offers {0.SimFirstName} the chance to go back to school in a work-study program (bachelor's degree) while staying employed.", "La empresa propone a {0.SimFirstName} retomar los estudios en formación dual (grado universitario) sin dejar de ser empleado."),
'card40_title': ("Work-Study Offer", "Propuesta de formación dual"),
'card41_opt0_res0': ("The UPS held and {0.SimFirstName} shut everything down cleanly: no data lost.\n\nDid you know? A UPS is a big battery that gives you time to shut servers down without damaging them.", "El SAI ha aguantado y {0.SimFirstName} lo ha apagado todo correctamente: ningún dato perdido.\n\n¿Lo sabías? Un SAI es una gran batería que da tiempo a apagar los servidores sin dañarlos."),
'card41_opt0_res1': ("One machine didn't have time to shut down and needs repairs.\n\nDid you know? You can configure the UPS to shut servers down automatically.", "Una máquina no ha tenido tiempo de apagarse y hay que repararla.\n\n¿Lo sabías? Se puede configurar el SAI para que apague los servidores solo."),
'card41_opt0': ("Shut the servers down cleanly", "Apagar los servidores correctamente"),
'card41_opt1_res0': ("The batteries run out after 10 minutes: the servers stop abruptly. Database damaged!\n\nDid you know? A sudden power cut can corrupt data: that's why you shut down cleanly.", "Las baterías se agotan a los 10 minutos: los servidores se apagan de golpe. ¡Base de datos dañada!\n\n¿Lo sabías? Un corte brusco puede corromper los datos: por eso se apaga correctamente."),
'card41_opt1': ("Wait for the power to come back", "Esperar a que vuelva la luz"),
'card41_text': ("Power outage across the whole building! The server room is running on batteries.", "¡Corte de luz en todo el edificio! La sala de servidores aguanta con las baterías."),
'card41_title': ("Power Outage!", "¡Corte de luz!"),
'card42_opt0_res0': ("{0.SimFirstName} discovers large-scale virtualization. Their current company benefits too!\n\nDid you know? The cloud means renting servers from a hosting provider instead of keeping them on your premises.", "{0.SimFirstName} descubre la virtualización a gran escala. ¡Su empresa actual también sale ganando!\n\n¿Lo sabías? La nube consiste en alquilar servidores a un proveedor en lugar de tenerlos en tus instalaciones."),
'card42_opt0': ("Learn cloud skills to be ready", "Formarse en la nube para estar preparado"),
'card42_opt1_res0': ("{0.SimFirstName} stays loyal to the server room.\n\nDid you know? Many companies mix both: that's the \"hybrid cloud\".", "{0.SimFirstName} sigue fiel a su sala de servidores.\n\n¿Lo sabías? Muchas empresas combinan ambos: es la «nube híbrida»."),
'card42_opt1': ("Stick with on-premises servers", "Quedarse con los servidores locales"),
'card42_text': ("A big cloud provider offers {0.SimFirstName} a job: \"Here, everything is automated, we run thousands of servers!\"", "Un gran proveedor de nube ofrece un puesto a {0.SimFirstName}: «¡Aquí todo está automatizado, gestionamos miles de servidores!»"),
'card42_title': ("A Cloud Provider Is Hiring", "Un proveedor de nube contrata"),
'card43_opt0_res0': ("Accepted! {0.SimFirstName} comes back with new skills and lots of prestige.\n\nDid you know? National cybersecurity agencies (like ANSSI in France) protect governments and key companies from cyberattacks.", "¡Aceptado! {0.SimFirstName} vuelve con nuevas competencias y mucho prestigio.\n\n¿Lo sabías? Las agencias nacionales de ciberseguridad (en España, el INCIBE y el CCN) protegen a las administraciones y a las empresas clave de los ciberataques."),
'card43_opt0_res1': ("Rejected this time, but the selection was very tough.\n\nDid you know? CTFs (ethical hacking competitions, like Root-Me) are great training.", "Rechazado esta vez, pero la selección era muy dura.\n\n¿Lo sabías? Los CTF (competiciones de hacking ético, como Root-Me) son un entrenamiento estupendo."),
'card43_opt0': ("Apply for the training", "Presentarse a la formación"),
'card43_opt1_res0': ("{0.SimFirstName} prefers to stay with the team.\n\nDid you know? Public or private sector, cybersecurity experts are in high demand.", "{0.SimFirstName} prefiere quedarse en su equipo.\n\n¿Lo sabías? En el sector público o en el privado, los expertos en ciberseguridad están muy solicitados."),
'card43_opt1': ("Stay in the private sector", "Quedarse en el sector privado"),
'card43_text': ("The national cybersecurity agency is looking for profiles like {0.SimFirstName} for advanced training.", "La agencia nacional de ciberseguridad busca perfiles como el de {0.SimFirstName} para una formación avanzada."),
'card43_title': ("The National Agency Is Hiring", "La agencia nacional contrata"),
'card44_opt0_res0': ("The studio loves their code and offers a §2500 freelance gig!\n\nDid you know? A GitHub with personal projects often says more than a résumé.", "¡Al estudio le encanta su código y le ofrece una misión freelance pagada con 2500 §!\n\n¿Lo sabías? Un GitHub con proyectos personales suele decir más que un currículum."),
'card44_opt0_res1': ("Didn't make it, but {0.SimFirstName} learned a lot about game engines.\n\nDid you know? Video games are an exciting but very demanding industry.", "No ha salido, pero {0.SimFirstName} ha aprendido mucho sobre motores de juego.\n\n¿Lo sabías? Los videojuegos son un sector apasionante pero muy exigente."),
'card44_opt0': ("Take the test", "Hacer la prueba"),
'card44_opt1_res0': ("{0.SimFirstName} sticks with current projects.\n\nDid you know? Keeping a side project lets you keep learning.", "{0.SimFirstName} sigue con sus proyectos actuales.\n\n¿Lo sabías? Mantener un proyecto personal permite seguir aprendiendo."),
'card44_opt1': ("Decline", "Declinar"),
'card44_text': ("A video game studio saw {0.SimFirstName}'s GitHub and offers a coding test.", "Un estudio de videojuegos ha visto el GitHub de {0.SimFirstName} y le propone una prueba de código."),
'card44_title': ("A Video Game Studio", "Un estudio de videojuegos"),
'card45_opt0_res0': ("DHCP hands out addresses again, everyone can connect.\n\nDid you know? An address starting with 169.254 means the PC didn't find a DHCP server (or it had no free addresses left).", "El DHCP vuelve a repartir direcciones y todos se conectan.\n\n¿Lo sabías? Una dirección 169.254 significa que el equipo no ha encontrado servidor DHCP (o que no quedaban direcciones libres)."),
'card45_opt0_res1': ("{0.SimFirstName} gets the mask wrong and cuts off part of the network.\n\nDid you know? Always check the subnet mask before changing a range.", "{0.SimFirstName} se equivoca de máscara y corta parte de la red.\n\n¿Lo sabías? Siempre se comprueba la máscara de subred antes de modificar un rango."),
'card45_opt0': ("Enlarge the DHCP server's range", "Ampliar el rango del servidor DHCP"),
'card45_opt1_res0': ("It works… until the day two PCs have the same address.\n\nDid you know? Setting static addresses by hand creates conflicts: DHCP exists precisely to avoid that.", "Funciona… hasta el día en que dos equipos tienen la misma dirección.\n\n¿Lo sabías? Las direcciones fijas puestas a mano crean conflictos: el DHCP sirve justamente para evitarlo."),
'card45_opt1': ("Set static addresses by hand", "Poner direcciones fijas a mano"),
'card45_text': ("In the morning, several new PCs can't reach the network: \"IP address 169.254.x.x\".", "Por la mañana, varios equipos nuevos no tienen red: «Dirección IP 169.254.x.x»."),
'card45_title': ("Out of IP Addresses!", "¡No quedan direcciones IP!"),
'card46_opt0_res0': ("The DNS service had stopped. Restarted: the intranet is back!\n\nDid you know? DNS translates names (intranet.local) into IP addresses. If the name fails but the IP works, it's often DNS.", "El servicio DNS estaba parado. Reiniciado: ¡la intranet vuelve!\n\n¿Lo sabías? El DNS traduce los nombres (intranet.local) en direcciones IP. Si el nombre no funciona pero la IP sí, suele ser el DNS."),
'card46_opt0_res1': ("{0.SimFirstName} searches for a long time before finding it.\n\nDid you know? The nslookup command lets you test a DNS server.", "{0.SimFirstName} busca mucho tiempo antes de encontrarlo.\n\n¿Lo sabías? El comando nslookup permite probar un servidor DNS."),
'card46_opt0': ("Check the DNS server", "Revisar el servidor DNS"),
'card46_opt1_res0': ("It changes nothing: that wasn't the problem.\n\nDid you know? Before acting, identify which layer is causing the problem.", "No cambia nada: el problema no estaba ahí.\n\n¿Lo sabías? Antes de actuar, se identifica la capa que da problemas."),
'card46_opt1': ("Restart the web server", "Reiniciar el servidor web"),
'card46_text': ("Nobody can open the intranet, but typing its IP address works.", "Nadie consigue abrir la intranet, pero escribiendo su dirección IP sí se abre."),
'card46_title': ("The Site \"Doesn't Work\"", "La web «no funciona»"),
'card47_opt0_res0': ("Account unlocked in 2 minutes, payroll goes out on time.\n\nDid you know? In Active Directory, locking after several failed attempts protects against brute-force attacks.", "Cuenta desbloqueada en 2 minutos, las nóminas salen a tiempo.\n\n¿Lo sabías? En Active Directory, el bloqueo tras varios errores protege contra los ataques de fuerza bruta."),
'card47_opt0': ("Unlock it after verifying", "Desbloquear tras verificar"),
'card47_opt1_res0': ("Nobody gets locked out anymore… but hackers can try thousands of passwords.\n\nDid you know? Good security strikes a balance between protection and convenience.", "Ya nadie se bloquea… pero los atacantes pueden probar miles de contraseñas.\n\n¿Lo sabías? Una buena seguridad busca el equilibrio entre protección y comodidad."),
'card47_opt1': ("Remove the lockout for everyone", "Quitar el bloqueo para todos"),
'card47_text': ("An accountant typed the wrong password 5 times: her account is locked and she has to run payroll today.", "Una contable ha escrito mal su contraseña 5 veces: su cuenta está bloqueada y hoy tiene que hacer las nóminas."),
'card47_title': ("Locked Account", "Cuenta bloqueada"),
'card48_opt0_res0': ("One Group Policy, and all 200 PCs are updated at the next startup!\n\nDid you know? A GPO (Group Policy Object) automatically applies settings to every PC in a domain.", "¡Una directiva de grupo, y los 200 equipos están al día en el siguiente arranque!\n\n¿Lo sabías? Una GPO (directiva de grupo) aplica automáticamente ajustes en todos los equipos de un dominio."),
'card48_opt0_res1': ("The GPO was applied to the wrong group: only the servers got the new wallpaper.\n\nDid you know? A GPO applies to an organizational unit (OU): you have to pick the right one.", "La GPO se ha aplicado al grupo equivocado: solo los servidores tienen el nuevo fondo.\n\n¿Lo sabías? Una GPO se aplica a una unidad organizativa (OU): hay que elegir bien cuál."),
'card48_opt0': ("Create a GPO", "Crear una GPO"),
'card48_opt1_res0': ("{0.SimFirstName} spends the entire day on it.\n\nDid you know? Anything repeated on many machines can be automated.", "{0.SimFirstName} se pasa el día entero en ello.\n\n¿Lo sabías? Todo lo que se repite en muchos equipos se puede automatizar."),
'card48_opt1': ("Go to each PC", "Pasar por cada equipo"),
'card48_text': ("Management wants the same wallpaper with the logo on all 200 PCs, by tomorrow.", "La dirección quiere el mismo fondo de pantalla con el logo en los 200 equipos, para mañana."),
'card48_title': ("The Company Wallpaper", "El fondo de pantalla de la empresa"),
'card49_opt0_res0': ("All the access points were on the same channel! {0.SimFirstName} spreads them out and throughput triples.\n\nDid you know? On 2.4 GHz, you use channels 1, 6 and 11 so access points don't interfere with each other.", "¡Todos los puntos de acceso usaban el mismo canal! {0.SimFirstName} los reparte y la velocidad se triplica.\n\n¿Lo sabías? En 2,4 GHz se usan los canales 1, 6 y 11 para que los puntos de acceso no se molesten."),
'card49_opt0_res1': ("It's a little better, nothing more.\n\nDid you know? Thick walls and microwaves also disrupt Wi-Fi.", "Va un poco mejor, sin más.\n\n¿Lo sabías? Las paredes gruesas y los microondas también perturban el Wi-Fi."),
'card49_opt0': ("Analyze the Wi-Fi channels", "Analizar los canales Wi-Fi"),
'card49_opt1_res0': ("More power… and even more interference.\n\nDid you know? More power doesn't mean better Wi-Fi: what matters most is placing the access points well.", "Más potencia… y aún más interferencias.\n\n¿Lo sabías? Más potencia no significa mejor Wi-Fi: lo importante es colocar bien los puntos de acceso."),
'card49_opt1': ("Buy a more powerful access point", "Comprar un punto de acceso más potente"),
'card49_text': ("On the 3rd floor, the Wi-Fi is very slow. Users are complaining.", "En la 3.ª planta, el Wi-Fi va muy lento. Los usuarios se quejan."),
'card49_title': ("The Wi-Fi Is Crawling", "El Wi-Fi va lentísimo"),
'card50_opt0_res0': ("Someone had plugged a cable between two wall sockets! {0.SimFirstName} removes it and everything comes back.\n\nDid you know? A network loop makes packets circulate forever. The Spanning Tree Protocol (STP) prevents it.", "¡Alguien había conectado un cable entre dos tomas de pared! {0.SimFirstName} lo quita y todo vuelve.\n\n¿Lo sabías? Un bucle de red hace circular los paquetes sin fin. El protocolo Spanning Tree (STP) sirve para impedirlo."),
'card50_opt0_res1': ("{0.SimFirstName} takes an hour to find the faulty cable.\n\nDid you know? Enabling STP on the switches would have prevented the outage.", "{0.SimFirstName} tarda una hora en encontrar el cable culpable.\n\n¿Lo sabías? Activar STP en los switches habría evitado la avería."),
'card50_opt0': ("Look for a network loop", "Buscar un bucle de red"),
'card50_opt1_res0': ("The network comes back… then goes down again 5 minutes later.\n\nDid you know? Rebooting doesn't fix the cause: the loop is still there.", "La red vuelve… y se cae otra vez 5 minutos después.\n\n¿Lo sabías? Reiniciar no arregla la causa: el bucle sigue ahí."),
}
